typedef unsigned long long big_int;
extern "C" unsigned int strlen(const char *);

class stringx;
class string_buf {
    friend class stringx;
    friend stringx operator+(const stringx &, const char *);
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx {
    friend stringx operator+(const stringx &, const char *);
    char *chars;
    string_buf *my_buf;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
    const char *c_str() const { return chars; }
    bool empty() const { return chars[0] == '\0'; }
    void make_room(int size);
    void append(const stringx &);
    void append(const char *, int len = -1);
};

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx foo;
    int len = strlen(rhs);
    foo.make_room(len + lhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs, len);
    return foo;
}

class filespec {
public:
    stringx path;
    stringx name;
    stringx ext;
    explicit filespec(const stringx &s);
};

class os_developer_options {
public:
    enum strings_t { STRING_TEXTURE_DIR = 72 };
    static os_developer_options *inst();
    const stringx &get_string(strings_t value) const { return strings[value]; }
private:
    char flags[0x1c];
    stringx strings[1];
};

extern os_developer_options *os_developer_options_instance;
__asm__(".equ os_developer_options_instance, 0x0045B180");
inline os_developer_options *os_developer_options::inst() { return os_developer_options_instance; }

struct nglTexture;
struct nglMaterial {
    unsigned int Flags;
    nglTexture *Map;
    char padding[0x30];
    unsigned int MapBlendMode;
    unsigned int MapBlendModeConstant;
};

extern void nglReleaseTexture(nglTexture *);
extern void nglSetTexturePath(const char *);
extern nglTexture *nglLoadTextureA(const char *);
__asm__(".equ nglReleaseTexture__FP10nglTexture, 0x0039C820");
__asm__(".equ nglSetTexturePath__FPCc, 0x00395DE0");
__asm__(".equ nglLoadTextureA__FPCc, 0x0039C1C8");

class mat_fac {
public:
    void load_material(const stringx &file);
private:
    nglMaterial m_nglmat;
};

void mat_fac::load_material(const stringx &file)
{
    filespec pather(file);
    if (pather.path.empty())
        pather.path = os_developer_options::inst()->get_string(os_developer_options::STRING_TEXTURE_DIR) + "\\";

    if (m_nglmat.Map)
        nglReleaseTexture(m_nglmat.Map);

    nglSetTexturePath((char *)pather.path.c_str());
    m_nglmat.Map = nglLoadTextureA((char *)pather.name.c_str());
    m_nglmat.Flags |= 0x10;
    m_nglmat.MapBlendMode = 1;
    m_nglmat.MapBlendModeConstant = 255;
}
